// Custom RAII wrapper for dynamic allocation
class ArrayGuard {
    int* ptr_;
public:
    explicit ArrayGuard(size_t s) : ptr_(new int[s]) {}
    ~ArrayGuard() { delete[] ptr_; }

    // Disable copying (essential for resource ownership)
    ArrayGuard(const ArrayGuard&) = delete;
    ArrayGuard& operator=(const ArrayGuard&) = delete;
};

